package ktanesolver.module.modded.regular.cruel_countdown;import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.countdown.*;
@Service@ModuleInfo(type=ModuleType.CRUEL_COUNTDOWN,id="cruelCountdown",name="Cruel Countdown",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Solve Countdown with banded random large numbers and small numbers up to fifteen.",tags={"numbers","arithmetic","timer","cruel"})
public class CruelCountdownSolver extends AbstractModuleSolver<CountdownInput,CountdownOutput>{@Override protected SolveResult<CountdownOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,CountdownInput input){if(input==null||input.numbers()==null||input.numbers().size()!=6||input.target()<100||input.target()>999)return failure("Enter the three-digit target and all six numbers");List<Integer>numbers=input.numbers();if(numbers.stream().anyMatch(x->x==null||!valid(x)))return failure("Numbers must be 1–15 or inside one of the four cruel large-number bands");long large=numbers.stream().filter(x->x>15).count();if(large<1||large>4)return failure("Cruel Countdown has from one to four large numbers");if(numbers.subList(0,(int)large).stream().anyMatch(x->x<=15)||numbers.subList((int)large,6).stream().anyMatch(x->x>15))return failure("Enter the large numbers first, as displayed");Set<Integer>bands=new HashSet<>();for(int i=0;i<large;i++)if(!bands.add(band(numbers.get(i))))return failure("Large numbers must come from distinct bands");CountdownOutput output=CountdownSolver.calculate(numbers,input.target());return output==null?failure("No legal Cruel Countdown solution was found"):success(output);}private static boolean valid(int n){return n>=1&&n<=15||n>=21&&n<=39||n>=41&&n<=59||n>=61&&n<=79||n>=81&&n<=99;}private static int band(int n){return n/20;}}
